@Component("sensorInstance-subscriber")
public class SensorInstanceSubscriber extends BaseSubscriber {

	public SensorInstanceSubscriber() {
	}
	
    public SubscriptionQueryResult<List<SensorInstance>, SensorInstance> sensorInstanceSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllSensorInstanceQuery(), 
                		ResponseTypes.multipleInstancesOf(SensorInstance.class),
                		ResponseTypes.instanceOf(SensorInstance.class));
    }

    public SubscriptionQueryResult<SensorInstance, SensorInstance> sensorInstanceSubscribe(@DestinationVariable UUID sensorInstanceId) {
        return queryGateway
                .subscriptionQuery(new FindSensorInstanceQuery(new LoadSensorInstanceFilter(sensorInstanceId)), 
                		ResponseTypes.instanceOf(SensorInstance.class),
                		ResponseTypes.instanceOf(SensorInstance.class));
    }





}

